#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    if (!(cin >> n)) return 0;

    long long cnt = n;
    long long sum = 0;
    vector<long long> primes;

    for (long long i = 2; i <= n / i; ++i) {
        while (n % i == 0) {
            primes.push_back(i);
            n /= i;
        }
    }

    if (n > 1) primes.push_back(n);

    for (long long prime : primes) {
        sum += cnt;
        cnt /= prime;
    }

    cout << sum + 1 << '\n';
    return 0;
}

